# :employee_submit_policy odrl:permission [ odrl:target :submit_expense_op ; odrl:assignee :employee ]
#   reached by :auto_approved, its start

EMPLOYEE_SUBMIT_POLICY_SUBMIT_EXPENSE_OP = Target(
    scenario=Scenario(
        iri="https://example.org/expenses/auto_approved",
        process="https://example.org/expenses/approval_process",
        key_variable="expense",
        key="auto_approved",
        start=Request(
            "POST",
            "/expenses/{expense}",
            "https://example.org/expenses/employee",
            (
                ("amount", "42.50"),
                ("date", "2026-10-01"),
                ("description", "Train to Leeds"),
            ),
        ),
        steps=(),
        entity_shape="https://example.org/expenses/ExpenseShape",
    ),
    at=0,
)


def test_policy_employee_submit_policy_submit_expense_op_allows_employee(app):
    result = attempt(*app, EMPLOYEE_SUBMIT_POLICY_SUBMIT_EXPENSE_OP, "https://example.org/expenses/employee")
    assert result.status == 200, result.text


def test_policy_employee_submit_policy_submit_expense_op_denies_finance(app):
    result = attempt(*app, EMPLOYEE_SUBMIT_POLICY_SUBMIT_EXPENSE_OP, "https://example.org/expenses/finance")
    assert result.status == 403, result.text
    assert result.detail["type"] == "PolicyDenied", result.detail
    assert result.detail["policy"] == "https://example.org/expenses/employee_submit_policy", result.detail
    assert result.unchanged, "a denied request changed the store"


